"use client";
import { useEffect, useRef, useState } from "react";
import { api, ApiError } from "../lib/api";

type User = { id: number; name: string; email: string; role: string };
const LETTERS: Record<string, string> = {
  aktif_kuliah: "Keterangan aktif kuliah",
  rekomendasi_beasiswa: "Rekomendasi beasiswa",
  cuti_akademik: "Cuti akademik",
};
const SUGGEST = [
  "Berapa maksimal SKS yang boleh diambil?",
  "Syarat beasiswa prestasi apa saja?",
  "Bagaimana cara mengajukan cuti?",
  "WiFi di lab mati, tolong dibantu",
];

// Helper: ambil pesan error yang ramah dari exception apapun
function errMsg(x: unknown): string {
  if (x instanceof ApiError) {
    if (x.status === 403) return "Fitur ini hanya tersedia untuk staf kampus.";
    if (x.status === 401) return "Sesi berakhir, silakan masuk kembali.";
    return x.message;
  }
  if (x instanceof Error) return x.message;
  return "Terjadi kesalahan, coba lagi.";
}

export default function Home() {
  const [user, setUser] = useState<User | null>(null);
  const [tab, setTab] = useState("chat");
  const [ready, setReady] = useState(false);

  useEffect(() => {
    async function checkAuth() {
      try {
        const u = await api("/auth/me");
        setUser(u);
      } catch {
        localStorage.removeItem("token");
      } finally {
        setReady(true);
      }
    }
    checkAuth();
  }, []);

  if (!ready) return null;
  if (!user) return <Login onDone={setUser} />;

  const staff = user.role !== "student";
  const tabs = [
    ["chat", "Asisten AI"],
    ["tickets", "Tiket layanan"],
    ["letters", "Surat otomatis"],
    ["docs", "Basis pengetahuan"],
    ...(staff ? [["analytics", "Analitik"]] : []),
  ];

  return (
    <div className="app">
      <nav className="rail">
        <div className="brand">
          <span className="dot" /> UniAgent
        </div>
        {tabs.map(([id, label]) => (
          <button
            key={id}
            className={"nav" + (tab === id ? " on" : "")}
            onClick={() => setTab(id)}
          >
            {label}
          </button>
        ))}
        <div className="who">
          {user.name}
          <small>{staff ? "Staf kampus" : "Mahasiswa"}</small>
          <button
            onClick={() => {
              localStorage.removeItem("token");
              setUser(null);
            }}
          >
            Keluar
          </button>
        </div>
      </nav>
      <main>
        {tab === "chat" && <Chat goto={(t) => setTab(t)} />}
        {tab === "tickets" && <Tickets staff={staff} />}
        {tab === "letters" && <Letters />}
        {tab === "docs" && <Docs staff={staff} />}
        {tab === "analytics" && <Analytics />}
      </main>
    </div>
  );
}

function Login({ onDone }: { onDone: (u: User) => void }) {
  const [email, setEmail] = useState("mahasiswa@uniagent.ac.id");
  const [password, setPassword] = useState("demo1234");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      const r = await api("/auth/login", {
        method: "POST",
        body: { email, password },
      });
      localStorage.setItem("token", r.token);
      onDone(r.user);
    } catch (x) {
      setErr(errMsg(x));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login">
      <section className="login-hero">
        <span className="orb" />
        <span className="orb two" />
        <h1>Urusan kampus selesai dalam satu percakapan.</h1>
        <p>
          Tanya aturan akademik, laporkan kendala, dan buat surat resmi. Jawaban
          diambil dari dokumen kampus, lengkap dengan sumbernya.
        </p>
      </section>
      <section className="login-form">
        <form onSubmit={submit}>
          <h2>Masuk ke UniAgent</h2>
          <input
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Email kampus"
            aria-label="Email"
            disabled={loading}
          />
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Kata sandi"
            aria-label="Kata sandi"
            disabled={loading}
          />
          {err && <div className="err">{err}</div>}
          <button className="btn" disabled={loading}>
            {loading ? "Memverifikasi..." : "Masuk"}
          </button>
          <p className="hint">
            Akun demo: mahasiswa@uniagent.ac.id atau staf@uniagent.ac.id, sandi
            demo1234
          </p>
        </form>
      </section>
    </div>
  );
}

function Chat({ goto }: { goto: (t: string) => void }) {
  const [msgs, setMsgs] = useState<any[]>([
    {
      role: "ai",
      text: "Halo! Saya UniAgent. Tanyakan soal KRS, beasiswa, cuti, atau laporkan kendala kampus.",
    },
  ]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const end = useRef<HTMLDivElement>(null);

  useEffect(() => {
    end.current?.scrollIntoView({ behavior: "smooth" });
  }, [msgs]);

  const send = async (text: string) => {
    if (!text.trim() || busy) return;
    setInput("");
    setBusy(true);
    setMsgs((m) => [...m, { role: "me", text }]);
    try {
      const r = await api("/chat", { method: "POST", body: { message: text } });
      setMsgs((m) => [
        ...m,
        {
          role: "ai",
          text: r.answer,
          sources: r.sources,
          action: r.action,
          intent: r.intent,
        },
      ]);
    } catch (x) {
      setMsgs((m) => [...m, { role: "ai", text: errMsg(x) }]);
    }
    setBusy(false);
  };

  return (
    <>
      <h1>Asisten AI</h1>
      <p className="sub">Jawaban bersumber dari dokumen resmi kampus.</p>
      <div className="card chat">
        <div className="msgs">
          {msgs.map((m, i) => (
            <div key={i} className={"bubble " + m.role}>
              {m.text}
              {(m.sources?.length > 0 || m.action) && (
                <div className="chips">
                  {m.sources?.map((s: any, j: number) => (
                    <span key={j} className="chip">
                      {s.title}
                    </span>
                  ))}
                  {m.action && (
                    <span
                      className="chip act"
                      onClick={() =>
                        goto(m.intent === "ticket" ? "tickets" : "letters")
                      }
                    >
                      {m.action}
                    </span>
                  )}
                </div>
              )}
            </div>
          ))}
          {busy && (
            <div className="bubble ai">Sedang mencari di dokumen kampus...</div>
          )}
          <div ref={end} />
        </div>
        <div className="suggest">
          {SUGGEST.map((s) => (
            <button key={s} className="chip" onClick={() => send(s)}>
              {s}
            </button>
          ))}
        </div>
        <div className="composer">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && send(input)}
            placeholder="Tulis pertanyaan Anda"
            aria-label="Pesan"
            disabled={busy}
          />
          <button className="btn" onClick={() => send(input)} disabled={busy}>
            Kirim
          </button>
        </div>
      </div>
    </>
  );
}

function Tickets({ staff }: { staff: boolean }) {
  const [items, setItems] = useState<any[]>([]);
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const load = async () => {
    try {
      const data = await api("/tickets");
      setItems(data);
    } catch (x) {
      setErr(errMsg(x));
    }
  };

  useEffect(() => { load(); }, []);

  const create = async () => {
    if (!title.trim()) return;
    setErr("");
    setLoading(true);
    try {
      await api("/tickets", { method: "POST", body: { title, description: desc } });
      setTitle("");
      setDesc("");
      await load();
    } catch (x) {
      setErr(errMsg(x));
    } finally {
      setLoading(false);
    }
  };

  const setStatus = async (id: number, status: string) => {
    try {
      await api(`/tickets/${id}`, { method: "PATCH", body: { status } });
      await load();
    } catch (x) {
      setErr(errMsg(x));
    }
  };

  return (
    <>
      <h1>Tiket layanan</h1>
      <p className="sub">
        Kategori dan prioritas ditentukan otomatis dari isi laporan.
      </p>
      {err && <div className="err" style={{ marginBottom: 12 }}>{err}</div>}
      <div className="card grid">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Judul laporan"
          aria-label="Judul"
          disabled={loading}
        />
        <textarea
          rows={3}
          value={desc}
          onChange={(e) => setDesc(e.target.value)}
          placeholder="Ceritakan kendalanya"
          aria-label="Deskripsi"
          disabled={loading}
        />
        <div>
          <button className="btn" onClick={create} disabled={loading}>
            {loading ? "Mengirim..." : "Kirim laporan"}
          </button>
        </div>
      </div>
      <div className="list">
        {items.length === 0 && (
          <div className="card">
            Belum ada tiket. Kirim laporan pertama Anda di atas.
          </div>
        )}
        {items.map((t) => (
          <div key={t.id} className="card tk">
            <div>
              <b>{t.title}</b>
              <p>{t.description}</p>
              <div className="row" style={{ marginTop: 8 }}>
                <span className="pill">{t.category}</span>
                <span className={"pill " + t.priority}>{t.priority}</span>
                <span className={"pill " + t.status}>{t.status}</span>
              </div>
            </div>
            {staff && (
              <select
                style={{ width: 130 }}
                value={t.status}
                onChange={(e) => setStatus(t.id, e.target.value)}
                aria-label="Ubah status"
              >
                <option value="open">open</option>
                <option value="proses">proses</option>
                <option value="selesai">selesai</option>
              </select>
            )}
          </div>
        ))}
      </div>
    </>
  );
}

function Letters() {
  const [type, setType] = useState("aktif_kuliah");
  const [purpose, setPurpose] = useState("");
  const [items, setItems] = useState<any[]>([]);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const load = async () => {
    try {
      const data = await api("/letters");
      setItems(data);
    } catch (x) {
      setErr(errMsg(x));
    }
  };

  useEffect(() => { load(); }, []);

  const create = async () => {
    setErr("");
    setLoading(true);
    try {
      await api("/letters", { method: "POST", body: { type, purpose } });
      setPurpose("");
      await load();
    } catch (x) {
      setErr(errMsg(x));
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <h1>Surat otomatis</h1>
      <p className="sub">Data diri diisi dari profil mahasiswa Anda.</p>
      {err && <div className="err" style={{ marginBottom: 12 }}>{err}</div>}
      <div className="card grid g2">
        <select
          value={type}
          onChange={(e) => setType(e.target.value)}
          aria-label="Jenis surat"
          disabled={loading}
        >
          {Object.entries(LETTERS).map(([k, v]) => (
            <option key={k} value={k}>{v}</option>
          ))}
        </select>
        <input
          value={purpose}
          onChange={(e) => setPurpose(e.target.value)}
          placeholder="Keperluan surat (contoh: melamar kerja)"
          aria-label="Keperluan"
          disabled={loading}
        />
        <div>
          <button className="btn gold" onClick={create} disabled={loading}>
            {loading ? "Membuat surat..." : "Buat surat"}
          </button>
        </div>
      </div>
      <div className="list">
        {items.length === 0 && (
          <div className="card" style={{ color: "var(--muted)" }}>
            Belum ada surat. Buat surat pertama Anda di atas.
          </div>
        )}
        {items.map((l) => (
          <div key={l.id} className="card">
            <div
              className="row"
              style={{ justifyContent: "space-between", marginBottom: 12 }}
            >
              <b>{LETTERS[l.type] ?? l.type}</b>
              <button className="btn ghost" onClick={() => window.print()}>
                Cetak
              </button>
            </div>
            <pre className="letter">{l.body}</pre>
          </div>
        ))}
      </div>
    </>
  );
}

function Docs({ staff }: { staff: boolean }) {
  const [docs, setDocs] = useState<any[]>([]);
  const [q, setQ] = useState("");
  const [hits, setHits] = useState<any[] | null>(null);
  const [addForm, setAddForm] = useState({ title: "", category: "umum", content: "" });
  const [upForm, setUpForm] = useState({ title: "", category: "umum" });
  const [file, setFile] = useState<File | null>(null);
  const [addErr, setAddErr] = useState("");
  const [upErr, setUpErr] = useState("");
  const [loadErr, setLoadErr] = useState("");

  const load = async () => {
    try {
      const data = await api("/documents");
      setDocs(data);
    } catch (x) {
      setLoadErr(errMsg(x));
    }
  };

  useEffect(() => { load(); }, []);

  const find = async () => {
    if (!q.trim()) { setHits(null); return; }
    try {
      const data = await api("/documents/search?q=" + encodeURIComponent(q));
      setHits(data);
    } catch (x) {
      setHits([]);
    }
  };

  const add = async () => {
    setAddErr("");
    if (!addForm.title.trim() || !addForm.content.trim()) {
      setAddErr("Judul dan isi dokumen wajib diisi.");
      return;
    }
    try {
      await api("/documents", { method: "POST", body: addForm });
      setAddForm({ title: "", category: "umum", content: "" });
      await load();
    } catch (x) {
      setAddErr(errMsg(x));
    }
  };

  const uploadFile = async () => {
    setUpErr("");
    if (!file) { setUpErr("Pilih file terlebih dahulu."); return; }
    if (!upForm.title.trim()) { setUpErr("Isi judul dokumen terlebih dahulu."); return; }
    const form = new FormData();
    form.append("title", upForm.title);
    form.append("category", upForm.category || "umum");
    form.append("file", file);
    try {
      await api("/documents/upload", { method: "POST", body: form });
      setFile(null);
      setUpForm({ title: "", category: "umum" });
      await load();
    } catch (x) {
      setUpErr(errMsg(x));
    }
  };

  return (
    <>
      <h1>Basis pengetahuan</h1>
      <p className="sub">Dokumen ini menjadi sumber jawaban asisten AI.</p>

      {/* Pencarian */}
      <div className="card row">
        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && find()}
          placeholder="Cari di dokumen kampus"
          aria-label="Cari"
        />
        <button className="btn" onClick={find}>Cari</button>
      </div>
      {hits && (
        <div className="list">
          {hits.length === 0 ? (
            <div className="card">Tidak ada hasil untuk pencarian ini.</div>
          ) : (
            hits.map((h, i) => (
              <div key={i} className="card">
                <b>{h.title}</b> <span className="chip">skor {h.score}</span>
                <p>{h.text}</p>
              </div>
            ))
          )}
        </div>
      )}

      {/* Form staff */}
      {staff && (
        <>
          {/* Form tambah teks */}
          <div className="card grid" style={{ marginTop: 18 }}>
            <b style={{ marginBottom: -8 }}>Tambah dokumen teks</b>
            <div className="row">
              <input
                value={addForm.title}
                onChange={(e) => setAddForm({ ...addForm, title: e.target.value })}
                placeholder="Judul dokumen"
                aria-label="Judul dokumen teks"
              />
              <input
                value={addForm.category}
                onChange={(e) => setAddForm({ ...addForm, category: e.target.value })}
                placeholder="Kategori"
                aria-label="Kategori dokumen teks"
              />
            </div>
            <textarea
              rows={4}
              value={addForm.content}
              onChange={(e) => setAddForm({ ...addForm, content: e.target.value })}
              placeholder="Isi dokumen"
              aria-label="Isi dokumen teks"
            />
            {addErr && <div className="err">{addErr}</div>}
            <div>
              <button className="btn gold" onClick={add}>Tambah dokumen</button>
            </div>
          </div>

          {/* Form upload file */}
          <div className="card grid" style={{ marginTop: 18 }}>
            <b style={{ marginBottom: -8 }}>Upload file dokumen</b>
            <div className="row">
              <input
                value={upForm.title}
                onChange={(e) => setUpForm({ ...upForm, title: e.target.value })}
                placeholder="Judul file yang diupload"
                aria-label="Judul file upload"
              />
              <input
                value={upForm.category}
                onChange={(e) => setUpForm({ ...upForm, category: e.target.value })}
                placeholder="Kategori"
                aria-label="Kategori file upload"
              />
            </div>
            <input
              type="file"
              accept=".txt,.md,.csv,.pdf,.docx"
              onChange={(e) => setFile(e.target.files?.[0] || null)}
              aria-label="Pilih file dokumen"
            />
            {upErr && <div className="err">{upErr}</div>}
            <div>
              <button className="btn" onClick={uploadFile}>Upload file dokumen</button>
            </div>
          </div>
        </>
      )}

      {/* Daftar dokumen */}
      {loadErr && <div className="err" style={{ marginTop: 12 }}>{loadErr}</div>}
      <div className="list">
        {docs.length === 0 && !loadErr && (
          <div className="card" style={{ color: "var(--muted)" }}>
            Belum ada dokumen di basis pengetahuan.
          </div>
        )}
        {docs.map((d) => (
          <div
            key={d.id}
            className="card row"
            style={{ justifyContent: "space-between" }}
          >
            <b>{d.title}</b>
            <span className="pill">{d.category}</span>
          </div>
        ))}
      </div>
    </>
  );
}

function Bars({ title, data }: { title: string; data: Record<string, number> }) {
  const max = Math.max(1, ...Object.values(data));
  return (
    <div className="card">
      <b>{title}</b>
      {Object.entries(data).map(([k, v]) => (
        <div key={k} className="bar">
          <span>{k}</span>
          <i style={{ width: `${(v / max) * 100}%` }} />
          <b>{v}</b>
        </div>
      ))}
    </div>
  );
}

function Analytics() {
  const [d, setD] = useState<any>(null);
  const [err, setErr] = useState("");

  useEffect(() => {
    async function fetchAnalytics() {
      try {
        const data = await api("/analytics");
        setD(data);
      } catch (x) {
        setErr(errMsg(x));
      }
    }
    fetchAnalytics();
  }, []);

  if (err) return (
    <div className="card" style={{ color: "var(--bad)", marginTop: 16 }}>
      {err}
    </div>
  );
  if (!d) return <p className="sub">Memuat data...</p>;

  const labels: Record<string, string> = {
    tickets: "Tiket",
    chats: "Percakapan",
    letters: "Surat",
    students: "Mahasiswa",
  };

  return (
    <>
      <h1>Analitik layanan</h1>
      <p className="sub">Ringkasan beban layanan kampus saat ini.</p>
      <div className="grid g4">
        {Object.entries(labels).map(([k, v]) => (
          <div key={k} className="card stat">
            <b>{d.totals[k]}</b>
            <span>{v}</span>
          </div>
        ))}
      </div>
      <div className="grid g2" style={{ marginTop: 16 }}>
        <Bars title="Tiket per kategori" data={d.tickets_by_category} />
        <Bars title="Status tiket" data={d.tickets_by_status} />
        <Bars title="Topik percakapan" data={d.chats_by_intent} />
      </div>
    </>
  );
}
